static const int kCount = 353;

// The glyph for code point cp, or nullptr.
inline const Glyph* Find(uint32_t cp)
{
    int lo = 0, hi = kCount - 1;
    while (lo <= hi)
    {
        const int mid = (lo + hi) / 2;
        if (kGlyphs[mid].cp == cp) return &kGlyphs[mid];
        if (kGlyphs[mid].cp < cp) lo = mid + 1;
        else hi = mid - 1;
    }
    return nullptr;
}
